22|async function getUserFromRequest(request: NextRequest) {
23|  const cookies = request.headers.get('cookie') || '';
24|  const token = getTokenFromCookie(cookies);
25|  if (!token) return null;
26|  const payload = await verifyToken(token);
27|  if (!payload) return null;
28|  const user = await prisma.user.findUnique({ where: { id: payload.sub } });
29|  return user;
