32|export async function GET(request: NextRequest) {
33|  try {
34|    const user = await getUserFromRequest(request);
35|    if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
36|
37|    const { searchParams } = new URL(request.url);
38|    const type = searchParams.get('type');
39|    const status = searchParams.get('status') || 'PUBLISHED';
40|    const page = parseInt(searchParams.get('page') || '1');
41|    const limit = parseInt(searchParams.get('limit') || '20');
42|    const q = searchParams.get('q');
43|
44|    const where: Record<string, unknown> = { status };
45|    if (type) where.type = type;
46|    if (q) {
47|      where.OR = [
48|        { title: { contains: q, mode: 'insensitive' } },
49|        { description: { contains: q, mode: 'insensitive' } },
50|      ];
51|    }
52|
53|    const [listings, total] = await Promise.all([
54|      prisma.listing.findMany({
55|        where,
56|        orderBy: { createdAt: 'desc' },
57|        skip: (page - 1) * limit,
58|        take: limit,
59|        include: {
60|          org: { select: { id: true, name: true, slug: true } },
61|        },
62|      }),
63|      prisma.listing.count({ where }),
64|    ]);
65|
66|    return NextResponse.json({
67|      listings,
68|      pagination: { page, limit, total, pages: Math.ceil(total / limit) },
69|    });
70|  } catch (error) {
71|    console.error('Listings fetch error:', error);
72|    return NextResponse.json({ error: 'Failed to fetch listings' }, { status: 500 });
73|  }
