76|export async function POST(request: NextRequest) {
77|  try {
78|    const user = await getUserFromRequest(request);
79|    if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
80|
81|    const body = await request.json();
82|    const validation = listingSchema.safeParse(body);
83|    if (!validation.success) {
84|      return NextResponse.json(
85|        { error: validation.error.errors[0].message },
86|        { status: 400 }
87|      );
88|    }
89|
90|    // Get or create default org for user
91|    let org = await prisma.organization.findFirst({
92|      where: { members: { some: { userId: user.id, role: 'OWNER' } } },
93|    });
94|    
95|    if (!org) {
96|      org = await prisma.organization.create({
97|        data: {
98|          name: user.name || user.email.split('@')[0],
99|          slug: user.email.split('@')[0].toLowerCase().replace(/[^a-z0-9]/g, ''),
100|          type: 'SOLE_PROPRIETOR',
101|          metadata: {} as Prisma.InputJsonValue,
102|          members: { create: { userId: user.id, role: 'OWNER' } },
103|        },
104|      });
105|    }
106|
107|    const data = validation.data;
108|    const listing = await prisma.listing.create({
109|      data: {
110|        orgId: org.id,
111|        type: data.type,
112|        title: data.title,
113|        description: data.description,
114|        pricing: data.pricing as unknown as Prisma.InputJsonValue,
115|        metadata: data.metadata as unknown as Prisma.InputJsonValue,
116|        status: 'PUBLISHED',
117|        publishedAt: new Date(),
118|      },
119|      include: { org: { select: { id: true, name: true, slug: true } } },
120|    });
121|
122|    await createAuditLog({
123|      userId: user.id,
124|      action: 'LISTING_CREATED',
125|      entity: 'listing',
126|      entityId: listing.id,
127|      newData: { type: listing.type, title: listing.title },
128|    });
129|
130|    return NextResponse.json({ listing }, { status: 201 });
131|  } catch (error) {
132|    console.error('Listing create error:', error);
133|    return NextResponse.json({ error: 'Failed to create listing' }, { status: 500 });
